INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (19, '헥토파이낸셜', '헥토파이낸셜', '1018163383', 894, 49420013, 219, '중견기업', '그 외 기타 금융 지원 서비스업', '코스닥', '서울 강남구 테헤란로34길 6 (역삼동, 태광타워) 9,10층', NULL, '2000년 10월 9일 설립된 이래로 끊임없는 혁신을 거듭해 온 헥토파이낸셜은
간편결제 시장점유율 1위, 가상계좌 시장점유율 1위, 펌뱅킹 월 5천만건 이상의 거래,
국내 유일 실시간 가상계좌 지방세 수납 시스템인 G뱅킹 등의 눈부신 성과를 이루어냈습니다.

하지만 헥토파이낸셜은 이에 안주하지 않고 ‘할 수 있다’는 지속적인 열정을 바탕으로 새로운 가능성에 도전하고 있습니다.
변화하는 결제 시장에 발맞춘 다양한 신사업을 통해 헥토파이낸셜의 사업을 다각화 시킬 뿐만 아니라
글로벌 시장의 진출을 통해 ‘Global FinTech Platform’ 기업으로 도약하겠습니다.

또한 헥토파이낸셜의 빛나는 성장에는 각 구성원들의 마음가짐과 역량이 바탕이 됨을 알고 있기에
각 개인이 자기 계발에 힘써 기업과 함께 성장할 수 있는 인재 존중의 기업 문화를 만들어가고 있습니다.

세계가 주목하는 Fintech 기업이 되겠다는 원대한 목표에 도전하고,
차별화된 경쟁력으로 시장을 선도하며
Financial Platform Leader 로서 헥토파이낸셜이 자리 매김할 것을 약속합니다.', 'enriched', true, NULL, NULL, '{"industry": "그 외 기타 금융 지원 서비스업", "hq_address": "서울 강남구 테헤란로34길 6 (역삼동, 태광타워) 9,10층", "company_type": "중견기업", "stock_status": "코스닥", "employee_count": 219, "company_name_jk": "㈜헥토파이낸셜"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
