INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (98, '쿠팡', '쿠팡', '1208800767', 53, 49437625, 13212, '대기업', '전자상거래 소매업', '-', '서울 송파구 송파대로 570 (신천동) 19층', NULL, '쿠팡은 고객이 쿠팡앱을 열어보는 순간부터 상품을 문 앞으로 배송 받는 순간까지, 고객 한 분 한 분에게 감동을 줄 수 있도록 쇼핑의 경험을 새롭게 창조하고 있습니다.

뛰어난 엔드투엔드(end-to-end) 이커머스와 물류 네트워크, 그리고 고집스러울 정도로 고객만을 생각하는 문화를 바탕으로 쿠팡은 속도, 셀렉션, 그리고 가격 중 그 무엇도 포기하지 않았습니다. 지금 쿠팡은 신선식품을 포함한 수백만 개의 상품이 단 몇 시간 내에 전국 단위로 1년 365일 배송되는 혁신을 실현하였습니다.

이 모두는 한국 이커머스 시장의 수백 만 고객을 위한 쿠팡의 노력입니다. 한국은 세계 어느 나라 보다 크고 빠르게 성장하는 이커머스 기회를 가진 시장입니다.', 'enriched', true, NULL, NULL, '{"industry": "전자상거래 소매업", "hq_address": "서울 송파구 송파대로 570 (신천동) 19층", "company_type": "대기업", "stock_status": "-", "employee_count": 13212, "company_name_jk": "쿠팡 주식회사"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (99, '인이지', '인이지', '6188701228', 30031, NULL, NULL, NULL, '전문, 과학기술', NULL, NULL, NULL, '안녕하세요. 인이지는 ‘인간을 이롭게 하는 인공지능’이라는 의미로 세상에서 가장 정확한 AI 예측 서비스를 제공하는 기업입니다. 2019년 설립 이후 산업용 공정최적화 및 예지보전 설명가능 AI 솔루션인 INFINITE OPTIMAL SERIES를 개발하여 국내 주요 화학, 반도체, 발전소 현장에서 ㈜인이지의 기술을 적용하고 있습니다. 현재 ㈜인이지는 계속해서 국내 레퍼런스를 확대하는 동시에 ‘23년 3월 일본지사를 설립 후 석유, 화학, 제약, 반도체 분야로의 세계시장 진출을 적극적으로 추진하고 있습니다.
세계 최고 수준의 AI 솔루션 기업인 (주)인이지에서 좋은 동료들과 함께 적극적으로 최고를 추구하며 성장해 나갈 분을 찾습니다.', 'name_mismatch', false, '와이엘컴퍼니 ', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
