INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (119, '마이일타', '마이일타', '3118603615', 53776, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '안녕하세요. 저희는 My1ta(마이일타)라는 이름으로 AI 기반 교육 플랫폼을 개발하고 있는 팀입니다.

‘내 손안의 1타 강사’라는 의미를 담고 있으며, 강사의 수작업을 자동화하고, 학생에게는 개인화된 학습 경험을 제공하는 것을 목표로 합니다.

