INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (120, '카이헬스', '카이헬스', '8188802407', 33138, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '- 카이헬스는 창업자가 10년 넘게 고민한 문제를 풀고자 합니다
카이헬스 창업자는 원래 난임병원에서 진료를 보던 산부인과 의사입니다 아기를 갖기가 힘든 분들이 난임 치료를 몇번씩 실패하고 힘들어 하시는 모습을 보면서 의료진의 경험에 의존하는 것보다 좀 더 나은 방법이 있지 않을까 항상 고민을 했었죠. 

- 아기를 갖고 싶어하는 부부의 15%는 난임으로 힘들어 하고 있습니다
아기를 낳는 시기가 조금씩 늦어지면서 전세계적으로 난임 인구는 늘어나고 있습니다. 그런데 난임 치료의 성공률은 여전히 한 사이클당 30% 내외로 낮아서, 한번도 받기 힘든 시술을 여러번 받아야 되는 경우가 대부분입니다

- 난임치료 성공률은 더 높아질 수 있습니다!
임신을 위해 제일 성공확률이 높은 배아를 골라 이식하는 것이 중요합니다. 현재는 의료진이 눈으로 보면서 주관적으로 고르고 있지만, 인공지능은 더 정확하고 객관적으로 좋은 배아를 고를 수 있습니다. 카이헬스는 배아 선택을 시작으로 정자, 난자 선택부터 프로토콜 최적화에 이르는 포괄적인 난임솔루션을 만들고자 합니다.', 'name_mismatch', false, '㈜이지컨트리클럽', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (121, '다이버(DiiVER)', '다이버', '7478701899', 23609, 49417206, 35, '중소기업', '쇼핑몰·오픈마켓·소셜커머스', '비상장', '서울 서대문구 연희로25길 62 (연희동) 1층 다이버', NULL, '“굿즈로 하는 브랜딩 파트너, DiiVER”

DiiVER는 ‘뛰어들다’는 뜻의 Dive와,
스쿠버다이빙에서 서로의 안전을 지키는 Buddy System에서 영감을 받아 탄생했습니다.

우리는 브랜드가 전하고자 하는 이야기를 함께 고민합니다.
굿즈, BX 디자인, 패키징은 물론, 공간과 온·오프라인 경험까지.
브랜드가 닿는 모든 접점에서 철학과 스토리를 자연스럽게 담아낼 수 있도록
기획부터 디자인, 제작, 유통까지 전 과정을 함께합니다.

DiiVER가 뛰어들고 있는 굿즈 산업은 국내 기준 30조 원이 넘는 거대한 시장입니다.
임직원 복지, 기업 마케팅/판촉, IP 머천다이즈 등 굿즈의 목적은 다양하지만,
그 중심에는 언제나 ‘브랜딩을 통한 팬 만들기’라는 공통된 목표가 자리합니다.

우리는 이 시장 속에서
단순한 제작사가 아닌,
브랜드의 정체성을 완성하는 파트너로 기억되길 바랍니다.

DiiVE DEEP TOGETHER!


 인스타그램 : https://www.instagram.com/diiver_official/
 네이버블로그 : https://blog.naver.com/diiver
 브런치 : https://brunch.co.kr/@diiver', 'enriched', true, NULL, NULL, '{"industry": "쇼핑몰·오픈마켓·소셜커머스", "hq_address": "서울 서대문구 연희로25길 62 (연희동) 1층 다이버", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 35, "company_name_jk": "㈜다이버"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (122, '쎄듀', '쎄듀', '2148747833', 42358, 49382147, 64, '중소기업', '출판·인쇄·사진', '비상장', '서울 강남구 논현로 305  (역삼동) 쎄듀타워', NULL, '㈜쎄듀는 2004년에 설립된 회사로 자본금 10억원, 매출액 159억만, 사원수 67명 규모의 중소기업입니다.
