INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (202, '앵커스', '앵커스', '6288800859', 21385, 49319072, 86, '중소기업', '웹에이전시', '비상장', '서울 마포구 양화로 125 (서교동, 경남관광빌딩) 9층, 10층', NULL, '앵커스는 2018년에 설립된 회사로 매출액 약 35억, 사원 수 40명 규모로 매년 50% 이상 성장하고 있습니다.
