INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (193, '룰루랩(lululab)', '룰루랩', '4358800655', 1732, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '“피부로 시작하는 설레는 미래”

정확한 피부 분석과 맞춤 솔루션으로 건강하고 아름다운 일상이 실현되는 미래가 바로 룰루랩이 추구하는 “피부로 시작하는 설레는 미래“입니다.

룰루랩은 17년 5월 삼성전자 C-Lab에서부터 시작하여 혁신적인 아이디어와 기술을 바탕으로 피부 데이터를 기반으로 한 뷰티-헬스케어 AI 솔루션을 개발하고 있습니다. 현재 전 세계 80만개 이상의 피부 데이터와 전문평가기관에서 검증된 피부분석 정확도 92% 이상의 AI 기술력을 보유하고 있습니다.

룰루랩의 피부 분석 AI 솔루션 ‘루미니’는 단 한 번의 촬영으로 얼굴 전체의 피부를 데이터화하여 분석하고, 적합한 화장품과 콘텐츠, 서비스를 추천해주는 서비스입니다. ‘루미니’는 그 기술력과 혁신성을 인정받아 세계최대가전 박람회 CES에서 2018년부터 4년 연속 혁신상 수상하였습니다. 또한 세계 3대 디자인 어워드인 레드닷 디자인 어워드와 if 디자인 어워드 등을 수상하며 상품성도 인정받고 있습니다. 룰루랩은 현재 ‘루미니’를 비롯하여 키오스크, 스마트 미러 등 하드웨어 제품을 개발하여, 국내뿐만 아니라 글로벌 뷰티 시장에 진출-판매하고 있으며, 모바일 앱으로 서비스를 확장시켜 나가고 있습니다. 

룰루랩은 ‘TRUE People’을 찾고 있습니다. 
‘Trustworthy’, 정직하고 믿을 수 있는 동료
‘Revolutionary’, 진취적이고 열정이 넘치는 동료
‘Understanding’, 이해하고 공감하는 동료
‘Elastic’, 자유롭고 유연한 사고를 지닌 동료

저희는 거짓말을 하지 않는 정직한 사람을 찾고 있습니다. 
진취성과 열정을 가지고 동료들과 협력을 통해 성과를 낼 수 있는 분을 모시고 싶습니다.
배려와 존중의 태도는 룰루랩에서 반드시 지켜야 할 자세입니다.

저희 룰루랩은 성공적 창업 경험을 가진 CEO와 글로벌 경력의 마케터와 디자이너, 삼성전자 최고의 알고리즘 개발자, 앱/서버 개발자와 뷰티 디바이스 경험이 있는 하드웨어 개발자까지, 모든 구성원들이 똘똘 뭉쳐 빠르게 성장하고 있습니다. 뛰어난 동료들과, 열정적으로 일하며, 뷰티-헬스케어 시장에 완전히 새로운 혁신을 일으킬 인재를 만나 뵙길 기대합니다.', 'not_found', NULL, NULL, NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (194, '오픈에이아이(OpenAI)', '오픈에이아이', '9999999999', 56952, NULL, NULL, NULL, '전문, 과학기술', NULL, NULL, NULL, '인류에게 유익한 방향의 범용 인공지능(AGI) 연구와 대규모 언어 모델 개발에 주력하는 세계적인 AI 연구 및 서비스 기업입니다. ChatGPT를 통해 복잡한 정보 처리를 돕고 인간의 생산성을 보조하는 혁신적 모델을 선보이며, 인공지능 기술이 일상의 실질적인 도구로 자리 잡는 시대를 개척하고 있습니다.', 'name_mismatch', false, 'CJ대한통운㈜	', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (195, '에이치에스소프트', '에이치에스소프트', '1318186072', 14627, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, 'HS SOFT는 피지컬 AI 기반 AI팩토리 전문기업으로,
제조 현장의 데이터·설비·시스템을 연결하는 제조 DX 플랫폼을 만듭니다.

