INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (300, '스마트푸드네트웍스', '스마트푸드네트웍스', '7198701744', 20767, NULL, NULL, NULL, '물류, 운송', NULL, NULL, NULL, '[외식업의 미래를 만드는 곳, 스마트푸드네트웍스]
스마트푸드네트웍스는 데이터와 기술로 외식업의 실질적인 문제를 해결하는 플랫폼 기업입니다.
전국 35,000여 개 매장과 71개 프랜차이즈 브랜드의 식자재 유통을 책임지며,
디지털·AI 전환을 통해 식자재 유통부터 매장 운영까지
외식업의 모든 과정을 효율화합니다.


[압도적인 성장, 검증된 잠재력]
설립 4년 만에 매출 3천억 원을 돌파했으며,
2025년 3월 시리즈C 투자 165억 원을 유치해
누적 투자 유치금 640억 원을 달성했습니다.
