INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (370, '지신', '지신', '3198803248', 54539, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '지신(JISHIN)은 AI·소프트웨어·하드웨어를 모두 직접 만드는 Full-Stack AI Product 스타트업입니다.

AI 모델 개발은 물론 HW 설계 및 제작, 그리고 설비와의 연동까지
