INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (371, '비케이씨앤씨', '비케이씨앤씨', '3478601993', 21537, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, 'BK Culture & Contents는 "맛있는 문화 한 모금"이라는 
슬로건 아래 "STRAW"라는 문화공유플랫폼을 2년 전에 
론칭했습니다.
극심한 코로나 상황에서 온-오프라인을 잇는 공연컨텐츠를 
성공적으로 운영한 후 현재 STRAW는 플랫폼서비스로 
