INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (376, '모빌린트', '모빌린트', '8768801379', 19686, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '“모든 사물이 인공지능을 갖는 편리한 세상”

모빌린트는 인공지능 기술의 무궁무진한 잠재력을 실현하여 더욱 편리하고 안전한 세상을 만들기 위해 2019년 설립된 AI 반도체 스타트업입니다. 
모빌린트는 KAIST에서 오랜 기간 딥러닝을 위한 AI 반도체를 연구하고 세계 최초로 인공지능을 위한 Edge ASIC Chip을 개발한 신동주 대표를 비롯해 인공지능, 소프트웨어, 반도체 설계 각 분야의 수준급 전문가들로 구성된 팀으로, 창사 1년 만에 글로벌 AI 반도체 벤치마크 테스트 MLPerf에서 국내최고수준의 성적을 거두고 MLPerf Founding Member로 등재되며 전 세계에 기술력을 인정받았습니다.

국내 AI 반도체의 다크호스로 급부상한 모빌린트는 지금까지 약 100억 원의 민간투자 및 90억 원의 정부지원 연구개발자금을 유치하며 기술개발에 박차를 가하고 있습니다. 

하드웨어의 한계로 상상만 하던 기술들을 현실로 만들고 인공지능의 새 시대를 열 설레는 여정, 모빌린트와 함께할 착하고 똑똑한 인재를 모십니다!', 'not_found', NULL, NULL, NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
