INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (404, '블래스트', '블래스트', '3508102289', 31166, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '블래스트는 Virtual Entertainment 회사로, 게임 엔진을 기반으로 실시간 그래픽으로 소통하는 미래를 만들어가고 있습니다. 
현재 버추얼 아티스트 PLAVE를 기획/제작/운영 중입니다. 
블래스트와 함께 Virtual Entertainment의 미래를 함께 만들어갈 우수한 인재의 지원을 환영합니다.', 'name_mismatch', false, '트렉바이시클코리아', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (405, '리비바이오', '리비바이오', '6958600419', 16075, 49198860, 86, '벤처기업', '모바일·APP', '비상장', '서울 강남구 역삼로3길 17 (역삼동) 6층(역삼동, 혜진빌딩)', NULL, '전세계 팬들을 위한 ​서비스를 ​만들고 ​있는 리비바이오팀에 ​합류하세요!

팬플러스/팬마음은 함께 덕질하는 재미를 느끼도록 돕고,
팬플러스/팬마음에서 ​이루는 ​것이 하나의 팬 문화로 자리 잡는 것을 ​꿈꾸고 있습니다.

우리는 `팬`들을 ​이 세상에서 누구보다 ​열정적인 사람들이라고 생각합니다.
누군가를 좋아하고 ​열렬히 응원하고 사랑하는 ​것은 그다지 일반적이지 ​않습니다.

엄청난 ​열정이 있어야 가능합니다.
우리는 이 세상 ​누구보다 열정적인 ​사람들의 생각과 행동, 그리고 ​이야기를 ​존중합니다.

이들이 ​만들어내는 모든 이야기는 ​큰 가치를 ​지니고 ​있어 전세계 ​팬들에게 소비되고 ​공유되어 ​K-POP 산업을 성장시키는 데 ​큰 역할을 ​합니다.
우리는 이러한 열정을 지닌 사람들이 팬플러스/팬마음 안에서 함께 덕질하는 재미를 느끼도록 돕고,
여기서 이루는 것이 하나의 팬 문화로 자리 잡는 꿈을 꾸고 있습니다.

#서비스 소개
팬플러스 : https://fanplus.co.kr
팬마음 : https://fanmaum.com/

