INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (471, '레벨스', '레벨스', '5738400041', 35184, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, 'LEVVELS Inc.는 2022년 1월, 글로벌 리딩 핀테크 기업인 Dunamu와 다국적 엔터테인먼트 기업 HYBE가 합작하여 설립한 회사입니다.
다가오는 시대에 걸맞는 최신 기술과 문화 콘텐츠를 결합하여 전 세계 고객들이 동시간대에 새롭고 즐거운 경험을 교류할 수 있도록 ‘Online playground culture’를 만들어나가고 있습니다.
문화를 사랑하는 전 세계 팬들은 LEVVELS Inc.를 통해 엔터테인먼트를 더욱 친숙하고 편리하게 경험할 수 있을 것입니다.
우리는 믿을 수 있는 IP를 확보하여 세심하게 콘텐츠를 선정, 제작하고 이를 고객에게 서비스하여 팬덤 모두가 새로운 즐거움을 나눌 수 있도록 최상의 기술 기반 서비스를 제공하는 것을 지향합니다.
우리는 문화를 사랑하는 전 세계 모든 이들이 일상 생활 속에서 새로운 즐거움과 영감을 받을 수 있는 공간을 만들고 있습니다.', 'name_mismatch', false, '레벨스 인크 (영업소)', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
