INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (474, '풀림', '풀림', '2670902360', 48720, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '풀림은 애드테크 기업입니다.

2022년 설립 이후 빠르게 성장해온 기업으로, 2025년 기준 사원수 32명, 매출액 180억 원의 성과를 달성했습니다.
더 큰 스케일업을 준비하는 2026년에는 200평대 규모의 업무 공간을 마련하며, 더욱 밀도 높은 협업과 성장을 위한 최적의 환경을 구축했습니다.

2026년, 기존 사업을 넘어 중고명품 리커머스, 온라인 교육, 종합마케팅, 외화 환전 플랫폼, 건강기능식품 브랜드 등 다양한 신사업으로 확장을 준비하고 있습니다.
이를 통해 사원수 150명, 매출 200% 성장을 목표로 더욱 공격적인 성장을 이어가고자 합니다.

우리는 혼자보다 함께의 가치를 더 중요하게 생각합니다.
단순한 협업을 넘어 서로의 성장을 진심으로 응원하는 문화 속에서 의미 있는 도전을 이어가고 있습니다.

자신의 업무를 정해진 테두리 안에만 가두지 않고, 프로덕트와 비즈니스를 함께 성장시킬 수 있는 아이디어를 제안하며 더 나은 성과를 만들어갈 분이라면, 풀림에서 그 여정을 함께해보시길 바랍니다.', 'name_mismatch', false, '반프', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (477, '아르고스아이덴티티코리아', '아르고스아이덴티티코리아', '3038600956', 18615, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '안녕하세요. 

