INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (484, '엠지알브이', '엠지알브이', '2188601128', 11292, 49436954, 104, '중소기업', '주거용 부동산 관리업', '비상장', '서울 성동구 왕십리로 125 (성수동1가, KD타워) 패스트파이브 서울숲점 1201호', NULL, 'MGRV는 새로운 삶의 가치를 제안하는 임팩트 디벨로퍼 Impact Developer 입니다.

