INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (538, '부동산플래닛', '부동산플래닛', '8818101896', 20909, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '부동산플래닛은 빅테이터 및 AI 기반 상업용 전문 프롭테크 기업입니다.
부동산 공간정보 및 빅테이터 분석 등을 통하여 다양한 데이터를 구축한 회사로 AI기술을 활용하여 전국 토지, 건물 부동산 추정가격을 제공하고 있으며, 상업용 부동산 투자, 임대, 관리, 매각까지 전 과정을 지원하는 부동산 종합 플랫폼을 구축해 나가고 있습니다.
또한, 데이터 기반의 자문 및 디지털 마케팅 역량을 바탕으로 매입/매각, 임대/임차 자문, 자산관리 서비스 등 풀스택 부동산 서비스를 제공하고 있습니다.', 'not_found', NULL, NULL, NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (539, '로그프레소', '로그프레소', '1218624069', 984, 49334140, 77, '중소기업', '시스템 소프트웨어 개발 및 공급업', '비상장', '서울 마포구 새창로 7 (도화동, 서울대학교 총동창회 장학빌딩) 9층', NULL, '로그프레소는 보안운영(SecOps) 플랫폼 전문 기업입니다. 클라우드와 온프레미스 보안 운영 업무를 완벽하게 통합할 수 있는 로그관리, 보안관제, 보안운영자동화 플랫폼을 공급하고 있습니다.

로그프레소는 2013년 설립 이래 KB국민은행, BNK부산은행, NH투자증권, 하나금융그룹, KT, LGU+, LG화학, SK하이닉스 등의 200여 고객사의 선택을 받아 왔습니다.

또한, 로그프레소는 2019년 프리 시리즈A(우리은행), 2023년 시리즈A(KB인베스트먼트, K2인베스트먼트, CJ인베스트먼트) 투자를 유치한 바 있고, 2022년, 2023년, 2024년 파이낸셜타임스 “아시아태평양지역 고성장기업 500”에 3년 연속 선정되었습니다.', 'enriched', true, NULL, NULL, '{"industry": "시스템 소프트웨어 개발 및 공급업", "hq_address": "서울 마포구 새창로 7 (도화동, 서울대학교 총동창회 장학빌딩) 9층", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 77, "company_name_jk": "㈜로그프레소"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (540, '샘표식품', '샘표식품', '4468700473', 14315, NULL, NULL, NULL, '제조', NULL, NULL, NULL, '샘표식품은 70여년 간 우리 장(醬)과 발효 연구에 몰두해 온 우리맛 중심의 전문 기업입니다. 
‘내 가족이 먹지 않는 것은 절대 만들지도 팔지도 않는다’는 창업주의 신념을 지금까지 지켜오며 간장 시장에서 부동의 1위를 지키고 있습니다. 
혁신적인 콩발효 기술로 한식의 DNA가 담긴 전통 조선간장을 복원해 대중화했으며, 100% 순식물성 콩발효 에센스 ‘연두’를 개발해 ‘요리에센스’ 시장을 개척했습니다. 
 또한 장(醬)과 다양한 식재료, 조리법 등을 체계적으로 분석하는 ‘우리맛 연구’를 통해 전 세계에 우리맛의 의미와 가치를 전하고 있습니다', 'name_mismatch', false, '쿠우쿠우 울산중구점', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (562, '트레드링스(Tradlinx)', '트레드링스', '5908600088', 414, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '국내 1위 수출입 물류 플랫폼 트레드링스는 2015년에 설립된 벤쳐기업으로
국내 최대 유저(300,000명+@)와 30,000개 수출입 기업들이 사용중인 수출입 물류 플랫폼 서비스를 제공하고 있습니다.

비효율적인 국제물류 시장에 21세기형 온라인 물류 플랫폼을 제공함으로써 기업의 수출입 업무를 오프라인에서 온라인으로 전환하고 A 부터 Z까지 관리할 수 있는 솔루션들로 효율화를 이루고 있습니다.

또한 플랫폼 서비스와 더불어 빅데이터 분석과 특허 알고리즘 등을 기반으로 수출입 물류에 필요한 다양한 기술을 지속적으로 개발하여 업계 최고 위치를 돈독히 굳히고 있습니다.

최근 두산, 이랜드, LS 등 국내 여러 대기업 들에 물류 솔루션 제공 계약 체결을 시작으로 빠른 성장을 이루고 있습니다. 빠르게 성장하는 서비스 규모에 대응하고 차세대 플랫폼 개발과 운영을 위하여 인원을 충원하고 있으며, 수출입 물류시장의 구글을 함께 이룰 책임감 있는 팀원을 찾고 있습니다.

