INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (568, '다이렉트클라우드랩', '다이렉트클라우드랩', '1208816459', 33615, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '다이렉트클라우드랩은 보안과 편리한 기능을 갖춘 클라우드 스토리지 서비스「DirectCloud」의 개발TEAM입니다.

공공기관 및 대기업부터 중소기업에 이르기까지 약 2,300여개의 고객사와 약 100만 명의 유저를 확보하였고, 프리시리즈 B 등 투자 유치에도 성공하며 성장가도를 달리고 있습니다.  또한, 이와 같은 성과를 바탕으로 2025년 일본에서 IPO를 준비하고 있습니다. 

AI 등 서비스 고도화를 통해 일본과 한국을 포함한 글로벌 시장 진출을 목표로 함께 성장해 나가실 역량있는 개발자 분들을 모시고자 합니다.', 'name_mismatch', false, '㈜구름네트웍스', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (569, '이오스시스템', '이오스시스템', '8938601138', 21328, NULL, NULL, NULL, '제조', NULL, NULL, NULL, '㈜이오스시스템은 2019년에 설립된 회사로 자본금 5억원, 매출액 87억 9,274만원, 사원수 49명 규모의 중소기업입니다. 
경기 안양시 만안구 안양로 424, 이오스빌딩 위치하고 있으며, 테이블오더 키오스크, 업소용/가정용 초음파세척기,음식물처리기,주방기기,설비,부동산임대업등등 제조/유통/금융업사업을 하고 있습니다.
', 'name_mismatch', false, '㈜구름네트웍스', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (570, '피플밤', '피플밤', '1278701931', 39597, 49357890, 4, '중소기업', '유선 온라인 게임 소프트웨어 개발 및 공급업', '비상장', '서울 강서구 마곡중앙10로 30 (마곡동, LG사이언스파크) 0', NULL, '피플밤은 F&B 시장의 오래된 거래 방식을 기술로 바꾸는 B2B F&B 플랫폼 스타트업입니다.

우리는 전화·메신저등에 머물러 있던 주문, 운영, 출고, 결제, 정산 업무를 하나의 플랫폼으로 연결하고 있습니다. 

단순 관리툴이 아니라 실제 거래가 발생하는 공급망 데이터를 기반으로 F&B 사업자의 운영 효율을 높이고, 향후 AI 기반 수요예측·거래처 관리·구매 최적화까지 확장하는 플랫폼을 만들고 있습니다.

서비스 출시 후 6개월만에 누적 거래액 40억 원을 돌파하며 시장의 빠른 반응을 확인했고, 현재도 고객 수와 거래액이 빠르게 증가하는 J커브 성장 구간에 있습니다.

피플밤은 아직 작지만, 빠르게 실행하고 빠르게 검증하는 팀입니다. 지금 합류하면 단순히 주어진 일을 수행하는 것이 아니라, 성장하는 F&B 플랫폼의 핵심 제품과 문화를 함께 만들어가는 초기 멤버가 될 수 있습니다.

우리는 문제를 직접 정의하고, 고객의 불편을 제품으로 해결하며, 시장에서 바로 검증되는 일을 좋아하는 분을 찾고 있습니다. 작은 팀에서 큰 임팩트를 만들고 싶은 분이라면 피플밤에서 가장 빠르게 성장할 수 있습니다.', 'enriched', true, NULL, NULL, '{"industry": "유선 온라인 게임 소프트웨어 개발 및 공급업", "hq_address": "서울 강서구 마곡중앙10로 30 (마곡동, LG사이언스파크) 0", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 4, "company_name_jk": "㈜피플밤"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (571, '라텔앤드파트너즈', '라텔앤드파트너즈', '7368601932', 31714, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '라텔앤드파트너즈는 IT 서비스 운영에 필요한 개발, 기획, 디자인, 마케팅까지 종합적인 업무프로세스를 수행하는 회사로 현재는 외국계 클라이언트의 서비스를 개발 및 운영하고 있습니다.

본사는 그동안의 기술력을 바탕으로 다수의 명곡을 작곡한 김형석 작곡가의 회사인 노느니특공대와 파트너쉽을 맺고, 김형석 작곡가와 함께 문화예술 분야와 IT기술을 융합한 혁신적인 신규 플랫폼 서비스를 준비 중에 있습니다.

라텔앤드파트너즈는 2020년에 설립한 회사로 자본금 1억원, 23년 매출액 36억원, 사원수 42명 규모의 중소기업입니다.
서울 중구 필동로 16 (필동2가 참그루빌딩)에 위치하고 있습니다.', 'not_found', NULL, NULL, NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (600, '에이슨', '에이슨', '7628801842', 45363, NULL, NULL, NULL, '전문, 과학기술', NULL, NULL, NULL, '에이슨은 웨어러블 바이오 센서 및 기기를 개발, 생산, 판매하는 스타트업입니다. 혁신적이며 편리하고 정확도가 높은 의료용 웨어러블 센서와 기기의 개발로 질병의 조기진단과 치료에 기여하고자 합니다', 'name_mismatch', false, '㈜윌로그', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (572, '이파피루스', '이파피루스', '2068191016', 4571, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '이파피루스는? 풍부한 경험과 탄탄한 기술력을 바탕으로 안정적이고 효율적인 전자문서 환경을 실현하는 문서AI 솔루션 전문기업입니다. 

■ 웹기반 문서 인프라 기업
 - 문서 라이프사이클을 아우르는 웹 기반 문서 인프라를 제공합니다
 - 누구나 쉽게 이용할 수 있는 스마트 문서 환경을 실현합니다
 - 국세청, 대법원 등 국내 주요 공공기관 및 네이버, 포스코, KB증권 등 대기업 업무 시스템에 사용되고 있습니다

■ 해외 진출과 사업 확장
 - 독보적인 문서 기술 및 노화우를 보유한 유수의 해외 자회사들과 함께합니다
 - Open AI의 "ChatGPT"에 PDF 솔루션 기술을 공급하고 있습니다
 - 인스탁스 시리즈 회사 "후지필름"에 고성능 PDL 엔진 ''ghostscript'' 기술을 공급하고 있습니다
 - AI 문서 질의 응답 서비스 ''Stream Docs.ai'' 출시하여 편의성 및 신뢰성 제공과 AI 환각 문제까지 해결한 혁신적인 서비스를 제공하고 있습니다.

■ 스마트 공장을 위한 예지보전
 - AI, 빅데이터, 클라우드, IoT 기술을 결합한 예지보전 솔루션을 제공합니다
 - 산업용 장비·설비 이상을 미리 감지하고 돌발 고장을 예방합니다
 - 삼성전자, 한화큐셀, 현대케피코, CJ제일제당 등 산업 현장 전 분야에서 활약합니다

이파피루스는 ''Document Infrastructure for the Web''이라는 비전 아래 글로벌 전자문서 인프라 플랫폼을 구축하기 위한 역량확보에 집중하고 있습니다.
이파피루스의 새로운 비전과 함께하며, 즐겁게 도전하고 싶은 분들께 포지션 제안 드립니다.

※ 이파피루스 홈페이지: https://epapyrus.com/
※ 이파피루스 블로그: https://epapyrus.tistory.com/', 'name_mismatch', false, '24시라인동물의료센터', NULL, NULL, '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (573, '케어랩스', '케어랩스', '2208836643', 10313, 49329684, 120, '중소기업', '광고·홍보·전시', '코스닥 상장', '서울 강남구 역삼로2길 16 (역삼동) 11층', NULL, '케어랩스 모바일 ​헬스케어 ​및 ​뷰티케어 분야의 ​No.1 플랫폼으로 도약하고 있습니다. ​우리는 ​의료 정보 ​불균형을 해소하고 모두가 ​의료 서비스를 ​편하게 ​받을 수 ​있도록 ​돕습니다. ​케어랩스는 헬스케어 미디어 ​사업, ​병원과 유저를 연결하는 ​플랫폼 ​굿닥, ​뷰티케어 플랫폼 바비톡, ​의료분야 전문 ​리크루팅 ​플랫폼 메디잡, ​의료 고객 ​전문 ​디지털 마케팅 사업, ​병의원 CRM ​소프트웨어, 처방전보안시스템 사업 등의 분야에서 유기적으로 협업하여 시너지를 창출합니다. 최근 국내외 총 14개 계열사를 운영하는 원익그룹에 편입되어 탄탄한 자본 구조를 바탕으로 가파른 성장세를 이어 나가고 있습니다.
', 'enriched', true, NULL, NULL, '{"industry": "광고·홍보·전시", "hq_address": "서울 강남구 역삼로2길 16 (역삼동) 11층", "company_type": "중소기업", "stock_status": "코스닥 상장", "employee_count": 120, "company_name_jk": "(주)케어랩스"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (574, '모니트', '모니트', '6138802063', 43952, 49308644, 12, '중소기업', '응용 소프트웨어 개발 및 공급업', '비상장', '경기 광명시 덕안로104번길 17 (일직동) 1510호(광명역M클러스터)', NULL, '전기차 충전 인프라', 'enriched', true, NULL, NULL, '{"industry": "응용 소프트웨어 개발 및 공급업", "hq_address": "경기 광명시 덕안로104번길 17 (일직동) 1510호(광명역M클러스터)", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 12, "company_name_jk": "모니트"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (575, '에이젠글로벌', '에이젠글로벌', '8038700360', 4396, 49423196, 32, '벤처기업', 'IT컨설팅', '비상장', '서울 영등포구 은행로 30 (여의도동, 중소기업중앙회) 8층', NULL, '에이젠글로벌(AIZEN Global)은 금융의 데이터, AI기반 의사결정(Decision-Making) 자동화를 통해 금융특화 ML솔루션 ‘ABACUS(아버커스)’ 및  AI뱅킹솔루션 ‘CreditConnect(크레딧커넥트)’를 한국 및 싱가포르,베트남, 인도네시아에 공급하고 있는 핀테크 기업입니다.
에이젠글로벌은 Citi, SC은행,SAP,IBM,삼성,Deloitte,EY 등 글로벌 금융회사, 컨설팅회사 출신의 매니지먼트팀이  글로벌 혁신을 만들고 있습니다.
국내 대형 금융회사에 AI금융솔루션 도입하였으며 우리은행, 우리카드, 현대카드, NH농협생명, 삼성생명 등이 솔루션을 사용하고 싱가포르, 베트남, 인도네시아에 전기자동차 금융서비스를 확장해 글로벌 사업을 진행하고 있습니다.빠르게 성장하는 인공지능 기업에 합류할 인재와 함께 글로벌 확장을 이어가겠습니다.', 'enriched', true, NULL, NULL, '{"industry": "IT컨설팅", "hq_address": "서울 영등포구 은행로 30 (여의도동, 중소기업중앙회) 8층", "company_type": "벤처기업", "stock_status": "비상장", "employee_count": 32, "company_name_jk": "㈜에이젠글로벌"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (576, '안드로메다의영웅들', '안드로메다의영웅들', '6088703194', 56230, 49393409, NULL, '중소기업', '전자상거래 소매업', '-', '경기 남양주시 별내중앙로 26 (별내동) 10층', NULL, '주식회사 안드로메다의 영웅들은 통신과 금융을 연결하는 마케팅·중개 플랫폼을 만드는 스타트업입니다. 

복잡하고 정보 비대칭적인 통신 요금제 구조를 기술로 단순화하여 누구나 쉽게 비교할 수 있도록 돕고, 
고객·통신사·제휴사 모두에게 데이터 기반의 독점적인 서비스 가치를 제공하는 것을 목표로 합니다.

통신사에서 서비스 기획을 담당해온 팀원 및 기술 전문가들을 중심으로, 
통신 요금제 마케팅·개통·수납·리텐션 데이터 중개 영역에 대한 깊은 도메인 이해를 바탕으로 실제 사업 성과를 만들어가고 있습니다. 

이통 3사 및 주요 제휴사와의 협업을 통해 실매출 기반으로 성장 중이며, 
단기 성과에 머무르지 않고 데이터 중심의 독점적 마케팅 중개 플랫폼으로 확장하고 있습니다.

소수 정예로 밀도 있게 일하며 시장을 재정의하는 관점으로 독점적 서비스를 만들어갑니다. 
각자의 전문성을 존중하고 결과로 말하는 문화를 지향하며, 함께 창조적 독점 서비스를 키우고 시장의 기준을 새롭게 만들어갈 동료를 기다립니다.', 'enriched', true, NULL, NULL, '{"industry": "전자상거래 소매업", "hq_address": "경기 남양주시 별내중앙로 26 (별내동) 10층", "company_type": "중소기업", "stock_status": "-", "employee_count": null, "company_name_jk": "㈜안드로메다의 영웅들"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (617, '누비랩', '누비랩', '1608801240', 11023, 49437797, 16, '중소기업', '응용 소프트웨어 개발 및 공급업', '비상장', '서울 강남구 테헤란로 625 (삼성동, 덕명빌딩) 덕명빌딩 6층', NULL, '[Inspire Today, Change Tomorrow]
세상에 없던 인사이트로 건강한 행동 변화를 만들어 갑니다

누비랩은 AI 기술과 데이터를 활용하여 고객 경험을 혁신하고, 개인 맞춤형 인사이트를 제공합니다. 고객들이 더 건강한 (Health) 행동으로 변화하도록 만들고, 더 나아가 지속가능한 성장을 위한 건강한(Good) 습관을 돕습니다.

2018년 말에 창업하여 2022년 10월 탑티어 투자사들로부터 100억 규모의 시리즈 A 투자 유치를 완료하였고, 국내외 파트너사들과 협업하며 빠르게 성장해 나가고 있습니다. ESG, 헬스케어, 푸드테크, AI 분야는 세계적으로 가장 빠르게 성장하고 있는 산업군에 속합니다. 누비랩과 함께 변화의 중심에서 인류와 지구의 건강을 지켜나갈 동료를 모십니다.', 'enriched', true, NULL, NULL, '{"industry": "응용 소프트웨어 개발 및 공급업", "hq_address": "서울 강남구 테헤란로 625 (삼성동, 덕명빌딩) 덕명빌딩 6층", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 16, "company_name_jk": "누비랩"}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (577, '나인닷츠컨설팅', '나인닷츠컨설팅', '1338801082', 27923, 49358143, 20, '중소기업', '솔루션·SI·CRM·ERP', '비상장', '서울 마포구 상암산로 76 (상암동, YTN 뉴스퀘어) 10층', NULL, 'Microsoft Business Solution 전문기업인 9 Dots Consulting 은 싱가폴에 본사를 두고 전세계 여러곳의 지사에서 고객의 비즈니스 성과 및 결과를 향상시키는데 주도적인 역할을 하고 있습니다. Microsoft 파트너사로서 고객사가 성장하고 트랜드를 선도하는데 필요한 업계 지식, 경험 및 솔루션을 보유하고 있습니다.

세계적으로 신뢰받는 business advisor 로 인정받고 있는 세계 최고의 비즈니스 솔루션 파트너입니다.

Microsoft Dynamics 365 환경에서 고객 기업의 프로세스를 관리하고 생성된 데이터를 분석하여 경영진에 insight를 제공하고 이를 통해 고객 기업의 가치를 높일 수 있도록 의사결정에 도움을 주는데 회사의 목적이 있습니다.

9 Dots Consulting 은 회사의 이익을 바라보지 않고 고객의 성장을 바라보는 정직한 경영에 기업의 비전이 있습니다.', 'enriched', true, NULL, NULL, '{"industry": "솔루션·SI·CRM·ERP", "hq_address": "서울 마포구 상암산로 76 (상암동, YTN 뉴스퀘어) 10층", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 20, "company_name_jk": "㈜나인닷츠컨설팅 "}', '2026-07-29 14:38:58.734046+09', '2026-07-29 14:38:58.734046+09', NULL, NULL);
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (578, '어반데이터랩', '어반데이터랩', '8648601386', 26340, 49474536, 30, '중소기업', '컴퓨터 프로그래밍 서비스업', '비상장', '서울 강남구 테헤란로 431 (삼성동, 저스트코타워(JustCoTower)) 6006호', NULL, '어반데이터랩은 인공지능과 클라우드형 플랫폼 구축 기술을 기반으로 헬스케어 서비스를 제공하는 기업입니다.

병원과 의료 연구 기관들이 가지고 있는 데이터는 아직 충분히 분석되고, 활용되지 못하고 있습니다. 
이로 인해 환자들과 의료진 모두에게 효율적이지 않은 서비스가 제공되고 있었습니다. 
어반데이터랩은 “이런 중요한 분야에서 기술이 환자와 의료진에게 실질적인 도움이 될 방법은 없을까?”에서 출발했습니다. 

헬스케어 혁신을 위해 어반데이터랩은 기존의 의료 데이터 디지털화, 복잡한 프로세스를 간소화하기 위한 플랫폼 구축 등 다양한 서비스들을 시도하고 있습니다. 
어반데이터랩이 목표로 하는 “모두가 건강한 세상”을 꿈꾸며 함께 새로운 방향으로 나아갈 분들을 기다리고 있겠습니다.

