INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (1865, '스위치원', '스위치원', '6188802127', 25500, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '스위치원은 외환 및 디지털 자산 트레이딩 그리고 외환 리스크 관리에 특화된 글로벌 핀테크 스타트업입니다. 
한국·일본·싱가포르 현지 법인을 기반으로 글로벌 외환 시장의 비효율을 기술로 해결하고 있습니다.

압도적인 성장세 (2026년 기준)
- 서비스 런칭 3년 반만에 연간 거래액 5조 원 규모로 성장
- 월간 4,500억 원 이상의 활발한 거래 처리
- 서울, 도쿄, 싱가포르를 잇는 글로벌 금융 네트워크 구축

독보적인 기술력
- 자체 외환 헤징 알고리즘 및 AI 환율 예측 모델 보유
- 24시간 외환/디지털 자산 트레이딩 앱 ''Switchwon'', 기업용 외환 관리 솔루션 ''Switchwon Biz'' 운영

스위치원 미션
스위치원 미션은 모두가 글로벌 금융의 혜택을 누릴 수 있는 세상을 만드는 것 입니다.

글로벌 핀테크 유니콘을 향해 나아가는 스위치원에서 최고의 동료들과 함께 성장할 분을 찾습니다. ', 'name_mismatch', false, '쿠팡로지스틱스서비스', NULL, NULL, '2026-08-04 22:56:14.259167+09', '2026-08-04 22:56:14.259167+09', NULL, 'wanted');
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (1866, '어크로스비', '어크로스비', '2998101933', 28603, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '어크로스비는 글로벌 이커머스 셀러가 사용하는 크로스보더 물류 플랫폼 "워크패드"를 만들고 있습니다. 주문, 배송, 재고, 상품 관리 등 물류 프로세스를 효율적으로 개선하여 원스톱 물류 서비스를 제공하고 있습니다.

우리의 목표는 IT기술을 통해 복잡한 물류 프로세스를 통합하고 글로벌 셀러가 비즈니스에만 집중할 수 있는 환경을 만드는 것입니다. 2020년 2월 서비스 출시 후 COSRX, 조선미녀, Anua, 코니, CLIO, thisisneverthat, KREAM 등 글로벌 시장에 진출하여 해외 소비자에게 사랑 받고 있는 많은 브랜드에서 워크패드를 사용하여 물류 업무를 진행하고 있습니다.

2020년 설립 이후 매년 매출이 2배 이상씩 성장하고 있으며, 여러 글로벌 투자사(스프링캠프, K2G, 중소벤처기업진흥공단, 오티엄캐피탈)로부터 34억원 규모의 누적투자를 유치하였습니다.', 'name_mismatch', false, '디케이스포츠단', NULL, NULL, '2026-08-04 22:56:14.270921+09', '2026-08-04 22:56:14.270921+09', NULL, 'wanted');
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (1867, '주식회사 풀리', '풀리', '8848104102', 58608, NULL, NULL, NULL, 'IT, 컨텐츠', NULL, NULL, NULL, '', 'pending', NULL, NULL, NULL, NULL, '2026-08-04 22:56:14.275921+09', '2026-08-04 22:56:14.275921+09', NULL, 'wanted');
INSERT INTO public.companies (id, name, normalized_name, registration_number, wanted_company_id, jobkorea_gno_ref, employee_count, company_type, industry, stock_status, hq_address, homepage, description, enrichment_status, name_match, rejected_name, enriched_at, raw_jobkorea, created_at, updated_at, logo_url, source) VALUES (1864, '다겸', '다겸', '4920401429', 26012, 49357679, 21, '중소기업', '솔루션·SI·CRM·ERP', '비상장', '서울 금천구 가산디지털1로 146 (가산동) 대륭테크노타운22차 802호', NULL, '저희 ''다겸(Dagyeom)''은 AI 빅데이터 전문기업으로서 데이터를 통한 최적의 컨설팅을 제공하고 있습니다. 실제로 데이터 분석 및 개발에 능숙한 젊고 유능한 데이터 전문가들로 구성된 다겸은 추천 알고리즘 개발과 데이터 가공 및 로그 분석, 텍스트와 이미지 분석을 통해 고객의 니즈와 비즈니스 환경에 최적화된 솔루션을 제공하고 있습니다. 이를 통해 AI 빅데이터 관련 다수의 프로젝트 수행 경력을 보유하고 있으며, 특히 온라인 쇼핑몰 데이터 분석에 관한 다수의 레퍼런스를 만들어 놓은 상태입니다.
자사는 2019년 4월 22일 사업자 등록을 시작으로 설립된 이후 정보 솔루션업을 사업 분야로 선정하고, 주요 솔루션으로 데이터 분석 및 소프트웨어 개발, 전자 상거래, AI 빅데이터 솔루션 개발을 제공하고 있습니다. 현재 다겸을 이끌고 있는 서대호 대표 역시 과거 한양대학교 정보시스템학을 전공한 뒤 한양대학원 산업공학 석사, 현재는 연세대학교 정보대학원 박사과정을 수료한 재원입니다. 이와 더불어 전 정부출연연구소(KAIST) 및 빅데이터 전문기업(모비젠) 재직의 경력을 보유한 지식과 실무능력 모두 두루 갖춘 8년차 AI 빅데이터 전문가입니다.', 'enriched', true, NULL, NULL, '{"industry": "솔루션·SI·CRM·ERP", "hq_address": "서울 금천구 가산디지털1로 146 (가산동) 대륭테크노타운22차 802호", "company_type": "중소기업", "stock_status": "비상장", "employee_count": 21, "company_name_jk": "다겸㈜"}', '2026-08-04 22:56:14.238701+09', '2026-08-05 00:32:27.835097+09', NULL, 'wanted');


