INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (842, 'wanted', 365672, 'https://www.wanted.co.kr/wd/365672', 320, '[청주] 어플리케이션 소프트웨어 엔지니어', '단편적인 코드 작성에 머무르지 않고, 소프트웨어 개발(Development)과 필드 엔지니어링(Field Engineering) 역량을 동시에 성장시킬 수 있는 하이브리드 포지션입니다.
3D 비전 검사 시스템의 핵심 제어 로직 설계부터 사용자가 장비를 제어하는 UI/UX 개발, 그리고 최종 고객 사이트 적용까지 전체 소프트웨어 라이프사이클을 전담합니다. 상용 비전 라이브러리와 하드웨어 간의 실시간 연동 인터페이스를 구축하고 시스템 제어 시퀀스를 구현합니다.', '• 고객 요구사항에 맞춘 3D 비전 ​검사 ​소프트웨어 개발
• 상용 ​비전 ​라이브러리 및 비전·​구동부 하드웨어 연동 ​기능 ​개발, 기술지원
• 소프트웨어 플랫폼 기반 ​시스템 ​제어 로직 설계 
