INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (673, 'wanted', 322285, 'https://www.wanted.co.kr/wd/322285', 466, '하드웨어 엔지니어', '㈜이투비비는 글로벌 위성항법시스템(GNSS)을 기반으로 한 정밀 시각·위치 솔루션을 개발하고 제공하는 전문 기업입니다. 당사는 GNSS시뮬레이터, 항재밍시스템, 타임서버, 원자시계, 실내측위 등 다양한 제품군을 통해 항공·국방·우주·통신·산업 전반에 걸쳐 안정적이고 신뢰할 수 있는 기술을 공급하고 있습니다.
또한, 국내 유일의 Safran 공식 대리점으로서 세계적으로 검증된 제품과 기술력을 보유하고 있으며, 이를 바탕으로 고객 맞춤형 솔루션과 전문적인 기술 지원을 제공하고 있습니다.', 'ㆍ안티드론 무력화 방어시스템 개발
ㆍ산업용 PC제작
ㆍ필드시험지원(FAE)
ㆍ하드웨어 회로설계
ㆍRF 신호 튜닝, GNSS 신호 튜닝
ㆍHigh power Amp', 'ㆍ학력 : 대졸이상
ㆍ경력 : 5년 이상', 'ㆍ정보통신, 정보처리기사 자격증 소지자 우대
ㆍ관련학과 우대', 'ㆍ4대보험
ㆍ연차제도, 주5일제
ㆍ건강검진
