INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (588, 'wanted', 365271, 'https://www.wanted.co.kr/wd/365271', 423, 'Manager, Live TV Technical Operations, APAC', 'Netflix is one of the world''s leading entertainment services, with over 300 million paid memberships in over 190 countries enjoying TV series, films and games across a wide variety of genres and languages. In this role, you will manage project-based live TV streaming technical operations for Netflix. Leading Live TV Technical Operations, you will help plan and execute all live project-based technical operations and work in collaboration with the Directors of Unscripted/ Live Content, Post Production, Live Streaming Pipeline Engineering Team and project/partner Production teams, and our Reliability Engineering teams.', '• Coordination and partnership across multiple stakeholders and clients for the smooth execution of live-streaming events
• Help draft, finalize, and maintain our Live Production Handbook that outlines key and critical technical and general guidelines for producing live content for Netflix
• Collaborate with contractors and in-house engineers for transmission planning
• Establish and maintain partnerships with satellite and IP transmission vendors, including estimating and booking of transmission pathways
• Establish and maintain partnerships with hardware and broadcast companies such as contribution/distribution encoder vendors, closed-captioning gears, and services
• Organize and maintain ground plans & drawings of venue infrastructures; draft and publish a detailed Technical Specifications booklet
• Act as a central resource for engineering and production, collaborating with teams to develop and execute technical plans, often managing concurrent schedules
• Responsible for troubleshooting, diagnosing, and reporting audio, video, and infrastructure issues in close collaboration with Netflix Engineering Team
• Participate in managing and evolving ground ingest capabilities, including signal acquisition, inspection, validation, and standardization
• Monitor the industry for emerging technologies and developing trends
• Be present on location for scouts/site visits, ESU, rehearsals, and actual live events; work flexible hours based on live events schedule
• Assume the role of lead Tech Manager or coordinate with freelance Tech Managers for larger-scale events
• Determine the best transmission method and coordinate with remote origination locations to ensure technical quality and readiness for air
• Work with other television entities, outside broadcasters, and vendors to identify, negotiate for, and secure required resources
• Maintain technical and broadcast quality including HDR, 4K, HD, Dolby or Stereo; work with production partners on hiring and managing technical crew', '• 10+ years of live broadcast remote operations experience (preferably network level) in a coordination or supervisory role
• Familiarity with digital audio/video fundamentals, compression technologies, distribution formats, and associated technologies such as Multicast and Unicast video distribution, MPEG Video (2, 4, & HEVC), MPEG-2 TS, HDR, SCTE-35 & ESNI signaling, closed-captions, satellite video distribution, and ad-splicing
• Familiarity with video transport protocols such as SDI, SMPTE-2110, RTP, RTMP, SRT, Zixi, RIST, HLS, MPEG-DASH
• Familiarity with Video and Audio Compression technology
• Understanding of nuances of remote production and the on-site technical operation
• Knowledge of remote production facilities and equipment vendors
• Familiarity with MVPD-based linear ecosystems and working knowledge of OTT video distribution, contribution technology, and architecture
• Ability to assess and troubleshoot video and audio quality
• Experience with on-premise video acquisition with partners or co-location facilities
• Fluency in English, Japanese and/or Korean is required', '• Experience with cloud-based workflows', '자세한 사항은 홈페이지 참조', '개발', '{"DevOps / 시스템 관리자","영상,음성 엔지니어","소프트웨어 엔지니어"}', 10, 100, false, true, 'regular', '한국', '서울', '종로구', '서울특별시 종로구 우정국로 26 (견지동, 센트로폴리스 A동 20층)', 37.5716155, 126.9833532, false, NULL, '2026-06-01 00:00:00+09', 'ACTIVE', '', '{}', '{}', false, '50만원', 'https://static.wanted.co.kr/images/company/56961/r71sziuiyhdtbbbt__1080_790.png', '{https://static.wanted.co.kr/images/company/56961/r71sziuiyhdtbbbt__1080_790.png,https://static.wanted.co.kr/images/company/56961/irpmgdjlofiedp1q__1080_790.png,https://static.wanted.co.kr/images/company/56961/x3wsnlsgvphyffam__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '10~100년', NULL, NULL, NULL, '2026-06-01 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Manager, Live TV Technical Operations, APAC', NULL);
