INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (610, 'wanted', 364879, 'https://www.wanted.co.kr/wd/364879', 431, '백엔드 개발자 (3년 이상)', '2013년 5월 20일에 설립된 와이즈버즈(KOSDAQ 273060)는 오직 진보된 기술을 통한 RTB Media 광고 효율 최적화에만 집중하고 있는 기업입니다.

자체 개발한 RTB Media 광고 최적화 플랫폼인 Adwitt은 2013년 대한민국 최초로 Facebook Preferred Marketing Developer (현 Facebook Marketing Partner 정책) Ads 배지를 획득하였으며, 2015년 Instagram Partner with Ad Tech Specialty에도 선정되어 와이즈버즈는 두 가지 배지를 모두 보유한 전세계 손 꼽히는 파트너사 중 하나가 되었습니다.

또한 검증된 RTB 광고 노하우를 통해 2017년 Google Premier Partner사로 선정되었으며 트위터, 카카오스토리, 링크드인, 더블클릭, 텐센트, 유니티와 같은 RTB 매체의 공식 Reseller이자 Leading Agency로 차별화된 서비스를 제공하고 있습니다. 특히 Band와 Vingle의 경우 RTB 시스템 및 노출 로직 구현에서부터 광고 등록 및 관리 플랫폼에 이르는 Ad Server 기술력 자체를 개발 및 공급하고 있으며 Head Sales Agency로 견고한 매체 성장까지 함께 이끌고 있습니다.

