INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (836, 'wanted', 369209, 'https://www.wanted.co.kr/wd/369209', 542, '프론트엔드 개발자 (Frontend Engineer)', '피노키오랩(주)은 Vision AI 기술을 기반으로 지식재산권 보호·위조상품 감정 분야의 AI 솔루션을 개발·운영하는 기업입니다. 유통(TIMS-D)·통관(TIMS-C)·글로벌 이커머스(TIMS-E) 단계의 위조상품 대응 솔루션을 무신사·롯데쇼핑·이랜드 등 주요 유통사 및 글로벌 이커머스와 함께 운영하고 있으며, ISO/IEC 27001 정보보호 관리시스템 인증을 보유하고 있습니다.

이번 채용은 한국지식재산보호원이 발주한 「AI 위조상품 감정지원 시스템 구축」 사업 수행을 위한 정규직 채용입니다. 소비자가 제출한 현품 이미지를 기반으로 AI가 1차 판독 근거를 생성하고, 내부관리자 검토와 상표권자 최종 확인을 거쳐 감정의견서를 발급·관리하는 업무형 AI 감정지원 플랫폼을 구축합니다.', '• AI 위조상품 감정지원 시스템의 화면 개발 (React 기반)
• 대민서비스(감정신청·결과확인), 관리자서비스(검토·승인), 상표권자서비스(최종확인) UI 개발
• 감정의견서 생성·조회 화면 및 이미지 기반 감정포인트 비교 화면 구현
• 백엔드 API 연동, 상태 관리, 예외·오류 처리 및 사용자 피드백 처리
• 반응형 UI/UX 구현 및 웹 접근성·크로스 브라우저 대응', '• 프론트엔드 개발 경력 3~5년 (정규직 기준)
• React 기반 SPA 개발 실무 경험
• JavaScript/TypeScript, HTML5, CSS3 활용 능력
• REST API 연동 및 비동기 데이터 처리 경험
• Git 기반 협업 및 코드 리뷰 경험', '• 코딩 에이전트(Claude Code, Cursor, GitHub Copilot 등 AI 코딩 도구) 활용 개발 경험
• 관리자 콘솔·업무 시스템 등 데이터 중심 화면 개발 경험
• 디자인 시스템/컴포넌트 라이브러리 구축·활용 경험
• TailwindCSS 등 유틸리티 기반 CSS 프레임워크 사용 경험
• 웹 접근성(WCAG)·전자정부 웹 표준 준수 경험
• 이미지 뷰어·비교 UI 등 시각화 컴포넌트 개발 경험
• 공공 SI 프로젝트 참여 경험', '• 강남 / 역삼역 도보 5분
• 동료와 원활한 협업을 위해 유연근무제 시행 (8 to 17, 9 to 18)
• 저녁, 간식, 음료 / 커피(pour over coffee) 지원
• 업무 관련 소프트웨어, 도서, 자료, 온라인 교육 수강비등 성장에 필요한 비용을 지원
• 원활한 업무를 위한 최신장비 지원
• 스톡옵션', '개발', '{"프론트엔드 개발자"}', 3, 5, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로13길 8-10, 2층 (역삼동, 동영빌딩) ', 37.50035630000001, 127.0332463, false, NULL, '2026-06-18 00:00:00+09', 'ACTIVE', '서류 전형 -＞ 1차 실무 면접 -＞ 2차 최종 면접 -＞ 처우 협의 -＞ 최종 합격', '{GitHub,Flutter}', '{1412,10176}', false, '100만원', 'https://static.wanted.co.kr/images/company/28314/c5ffmv7oewifcv59__1080_790.jpg', '{https://static.wanted.co.kr/images/company/28314/c5ffmv7oewifcv59__1080_790.jpg}', NULL, '2026-07-29 14:38:58.734046+09', '3~5년', NULL, NULL, NULL, '2026-06-18 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, '프론트엔드 개발자 (Frontend Engineer)', '[-0.083077,-0.113344,0.035924,0.018776,-0.007901,0.024306,-0.003937,-0.003402,0.028590,0.077350,-0.050277,0.012092,0.047206,0.027481,0.025818,0.001651,0.041766,-0.008857,0.065833,0.032298,0.005323,-0.085335,0.058531,-0.050507,-0.034068,0.012826,-0.019954,-0.041072,-0.032538,-0.089187,0.048993,-0.045600,0.031561,0.027833,-0.078816,0.042228,-0.043574,0.015696,-0.055329,-0.038304,-0.076830,0.064158,0.028447,-0.005596,0.023264,-0.005379,-0.027493,-0.056155,-0.094616,-0.031405,-0.039729,-0.108623,0.043405,0.003865,-0.013754,0.055735,0.043162,-0.019993,-0.033434,-0.028516,0.044118,-0.069343,0.001637,0.062632,-0.012089,0.076769,-0.025559,0.000212,0.030572,-0.156089,-0.048372,-0.042533,0.029844,-0.039251,0.046737,-0.045123,0.011565,0.038568,0.092772,-0.044775,0.055383,0.057461,0.038907,0.120159,0.022945,0.015930,-0.014460,0.048842,-0.029879,0.042249,0.021370,0.019221,0.054651,-0.025023,0.025838,0.003092,-0.047362,-0.082971,-0.014828,0.135293,-0.013225,-0.015850,-0.039303,-0.033334,0.030644,0.024158,0.061160,-0.063663,-0.058075,0.035465,-0.055132,-0.022045,-0.099139,-0.056067,0.047824,-0.011609,-0.075537,0.021943,0.079034,0.012501,0.033742,-0.026424,0.058073,-0.002088,0.113865,-0.023658,-0.101051,-0.033141,-0.053160,-0.008847,0.059828,0.060300,0.034255,-0.013552,-0.042521,0.008936,0.007660,