INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (992, 'wanted', 360058, 'https://www.wanted.co.kr/wd/360058', 79, 'Sr Delivery Consultant - Telco, Professional Services', 'The Amazon Web Services Professional Services (ProServe) team is seeking a skilled Senior Delivery Consultant with telecommunications industry specialization to join our team. In this role, you''ll work closely with telecommunications customers to design, implement, and manage AWS solutions that meet their technical requirements and business objectives. You''ll be a key player in driving customer success through their cloud journey, providing both strategic technical leadership and hands-on delivery expertise throughout the project lifecycle.', '• Design and implement complex, scalable, and secure AWS solutions tailored to telecommunications customer needs
• Lead technical and design discussions with telecom IT executives to help enterprises speed their adoption of new technologies and practices
• Architect cloud-native telecommunications solutions leveraging AWS services for network functions, edge computing, and 5G infrastructure
• Hands-on implementation of Infrastructure as Code (IaC), configuration management for telecom infrastructure and applications
• Build and manage release systems, code merging and promotion, and CI/CD workflows for telecom workloads
• Act as a trusted advisor to telecommunications customers on industry trends, emerging technologies, and innovative cloud solutions
• Lead customer discovery sessions that earn trust, uncover blockers, and document technical scope for telecom-specific workloads
• Manage projects independently and deliver as part of larger teams focused on telecom transformations
• Hands-on experience with architecting and automated provisioning using CloudFormation, Terraform, or other IaC tools
• Implement monitoring and log aggregating frameworks for telecom workloads
• Create and apply frameworks, methods, best practices and artifacts specific to telecommunications industry
• Share knowledge within the organization through mentoring, training, and creating reusable telecom-focused artifacts
• Publish and present telecom cloud solutions in large forums and across various media platforms
• Collaborate with AWS product teams to share telecom customer insights and identify product feature gaps
• Travel to client locations and deliver professional services as needed', '• Experience solving problems with technology in the Telecommunications industry
• Experience leading large teams, with demonstrable ability to hire, develop, and manage high-performing technical teams
• Bachelor''s degree in Computer Science, Engineering, Telecommunications, or related field, or equivalent experience
• Hands-on experience with AWS services relevant to telecommunications (e.g., EC2, VPC, Direct Connect, Wavelength, Local Zones)
• Hands-on experience with architecting and automated provisioning (IaC), configuration management for infrastructure and applications', '• Experience with telecommunications technologies including 5G, edge computing, network function virtualization (NFV), software-defined networking (SDN)
• Knowledge of telecom industry standards and compliance requirements (e.g., ETSI, 3GPP, regulatory frameworks)
• Understanding of telecom BSS/OSS systems and hands-on integration experience
• Knowledge of security and compliance standards relevant to telecommunications industry
• Experience with monitoring and log aggregating frameworks like CloudWatch, Datadog, Splunk, AWS X-Ray for telecom workloads
• Hands-on experience with microservices and distributed application architecture for telecom applications', '• Diverse experiences valued — candidates encouraged to apply even without meeting all qualifications
• Mentorship and career-advancing resources to develop into a better-rounded professional
• Inclusive team culture with employee-led affinity groups
• Work/life balance with flexibility as part of working culture
• Knowledge-sharing opportunities across a diverse global team of technical experts', '개발', '{"DevOps / 시스템 관리자","서버 개발자","소프트웨어 엔지니어"}', 5, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-05-07 00:00:00+09', 'ACTIVE', '', '{AWS}', '{1698}', true, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '5~100년', NULL, NULL, NULL, '2026-05-07 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Sr Delivery Consultant - Telco, Professional Services', '[-0.065559,0.035992,-0.057106,-0.004264,-0.055530,0.017175,0.021290,0.015122,0.007118,0.073511,-0.051678,0.021847,0.006206,0.026093,-0.002100,0.030637,-0.004183,-0.046477,0.042591,0.001489,-0.035730,-0.023763,-0.118226,-0.069668,-0.045792,-0.033721,0.046531,-0.011521,0.039076,-0.101559,0.046992,0.019251,0.014007,0.044054,-0.018547,0.085491,0.004860,-0.006483,-0.088402,-0.080274,0.022098,-0.004995,0.038045,0.014172,0.023416,-0.029873,-0.049091,0.045895,-0.127349,-0.014354,-0.040779,-0.065764,-0.007001,0.017393,-0.045296,0.061990,0.036311,0.091208,-0.026172,-0.077390,0.017068,-0.025106,-0.041956,0.036096,-0.060091,0.083657,-0.052706,0.001510,-0.001425,-0.075928,-0.105697,-0.108331,-0.081379,0.033377,0.040022,0.025759,0.033581,0.044407,0.082176,-0.019633,0.044221,0.034474,-0.006081,0.073558,-0.058782,0.068829,-0.050994,-0.016357,0.034434,-0.017898,0.044792,-0.041068,0.022071,-0.067159,-0.035578,-0.009964,-0.011968,-0.010528,-0.032234,0.111877,-0.022013,0.033882,0.013437,-0.044058,-0.063937,0.010217,-0.012979,-0.044638,0.003054,0.036207,-0.025224,-0.044791,-0.105534,-0.04