INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (984, 'wanted', 366541, 'https://www.wanted.co.kr/wd/366541', 180, 'Senior Application Support Engineer (Sales & Delivery Application), Seoul, Korea', 'Tesla is seeking a skilled Application Support Engineer to join our IT Application Team. This role is dedicated to providing outstanding support for sales and delivery-related applications, ensuring seamless operations and exceptional satisfaction for both customers and business stakeholders.', '• Provide production support for Tesla''s sales and delivery applications for APAC, including but not limited to Sales Applications, Order-to-Delivery Applications, and Ownership Applications.
• Support sales and delivery business operations by managing production incidents and basic requests, conducting thorough issue analysis, implementing immediate containment solutions, and recommending long-term resolutions.
• Serve as the primary point of contact for support requests related to sales and delivery applications, ensuring all requests are logged promptly, courteously, and accurately.
• Collaborate with business stakeholders and Product Engineer (PE) and drive application new feature implementation from end-to-end.
• Escalate unresolved issues within the IT department to guarantee timely resolution, maximize system up time for users, and oversee the full life cycle of issues with clear communication.
• Proactively monitor systems, identify, resolve, or mitigate production issues to minimize disruptions to sales operations and customer experience.
• Monitor system performance and stability, propose and implement system improvement for continuous optimization.
• Develop support tools to automate repetitive requests or issue resolution processes for sales and delivery applications.
• Collaborate with dev team, product team, and business team on testing and advanced support activities for sales and delivery systems.', '• BS in computer science or electrical engineering, MS preferred.
• 3+ years of experience in a support role, with a solid understanding of support processes and Service Level Agreements (SLAs).
• Coding experience, with hands-on expertise in developing and maintaining applications.
• Strong skills in root cause analysis and problem-solving.
• Product sense with the ability to understand product architecture and drive and criticize design decisions.
• Strong English and Korea communication skills, both written and verbal.
• Proficiency in SQL for database querying and analysis.
• Basic knowledge of infrastructure components, including networking, databases, and Kubernetes (K8S).
• Demonstrated ability to multitask and perform effectively under pressure.
• Adaptability to excel in a fast-paced, dynamic environment.', '• AI project experience is a plus.
• Programming skills in Python and/or .NET are a significant advantage.
• Familiarity with monitoring and logging tools such as Grafana and Splunk.', '자세한 사항은 홈페이지 참조', '개발', '{"DevOps / 시스템 관리자",기술지원,"소프트웨어 엔지니어"}', 3, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 419, 9층', 37.5058798, 127.0521319, false, NULL, '2026-06-05 00:00:00+09', 'ACTIVE', '', '{Python,Kubernetes,SQL,.NET,Excel}', '{1554,10268,1562,1445,1617}', true, '50만원', 'https://static.wanted.co.kr/images/company/56950/o52dya6kfjrcde6b__1080_790.png', '{https://static.wanted.co.kr/images/company/56950/o52dya6kfjrcde6b__1080_790.png,https://static.wanted.co.kr/images/company/56950/vx2jrggdznjgou0f__1080_790.png,https://static.wanted.co.kr/images/company/56950/gamxlehwud02w7td__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '3~100년', NULL, NULL, NULL, '2026-06-05 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Senior Application Support Engineer (Sales & Delivery Application), Seoul, Korea', '[-0.065545,0.043979,0.005854,-0.013458,-0.030262,-0.038315,-0.039738,0.033739,0.001797,-0.032039,-0.012333,0.031993,0.072939,-0.067516,-0.003194,-0.024195,0.067250,-0.002830,0.060315,-0.033071,-0.042667,-0.092672,0.028086,-0.055480,-0.056121,-0.005936,0.001679,0.074648,0.026090,-0.042365,-0.002087,0.007066,0.100661,-0.010558,0.044231,0.087462,-0.021041,-0.055594,-0.073328,-0.091632,-0.002274,0.067852,0.050390,0.039533,0.022283,0.027081,-0.053598,-0.031145,-0.080452,-0.023229,-0.023286,-0.034943,-0.041853,-0.128557,-0.032651,0.045559,0.078607,0.083255,0.025785,-0.024275,-0.030747,-0.111822,-0.097061,0.020101,-0.044140,-0.014537,-0.030561,0.059206,0.011233,-0.061973,0.013414,-0.059351,-0.044053,0.014454,-0.075694,-0.008323,0.022006,0.028743,0.002189,-0.034587,0.046875,-0.018443,-0.008450,0.040872,0.046055,0.041475,-0.027787,0.094113,0.039431,0.044039,0.035895,0.004630,0.022505,-0.044931,0.027077,0.025547,0.074309,-0.016611,-0.060509,0.088824,0.016947,0.057568,-0.015942,-0.051605,-0.054230,0.065444,0.1