INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (982, 'wanted', 367745, 'https://www.wanted.co.kr/wd/367745', 79, '2026 Career Enhanced Re-Start Program: Data Center Operation Trainee, DCO (Data Center Operations)', 'AWS Infrastructure Services owns the design, planning, delivery, and operation of all AWS global infrastructure. In other words, we''re the people who keep the cloud running. We support all AWS data centers and all of the servers, storage, networking, power, and cooling equipment that ensure our customers have continual access to the innovation they rely on. Data Center Operations designs, installs & maintains the world''s largest Cloud Computing Infrastructure.', '• Install and configure data center servers and network systems
• Perform hardware diagnostics and troubleshooting
• Replace hardware components in servers and network devices
• Manage storage media (HDD, SSD etc) operations, including sanitization and destruction
• Handle support tickets within defined Service Level Agreement (SLA)
• Work cross-functionally with internal data center operation teams
• Follow data center operations, security guidelines and safety standards
• Work on shift schedule covering 24/7 operations, including weekends', '• Can lift and rack equipment up to 40 pounds
• Knowledge of server hardware and components
• 교육 기간 및 정규직 전환 시 연속근무 가능하신 분', '• Bachelor''s degree in information technology or computer science
• Knowledge of IT system hardware and network concepts
• 주말을 포함한 24/7 데이터센터 운영을 위한 교대근무 가능하신 분', '• 3-month full-time contract position with opportunity to convert to full-time Data Center Operations position upon successful completion
• Comprehensive training in data center operations through structured mentorship
• Hands-on technical experience during program period
• Inclusive team culture with employee-led affinity groups
• Work/life balance with flexibility as part of working culture
• Endless knowledge-sharing, mentorship and career-advancing resources', '개발', '{"DevOps / 시스템 관리자",기술지원,"소프트웨어 엔지니어"}', NULL, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-06-11 00:00:00+09', 'ACTIVE', '', '{CAN}', '{2953}', true, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '경력무관', NULL, NULL, NULL, '2026-06-11 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, '2026 Career Enhanced Re-Start Program: Data Center Operation Trainee, DCO (Data Center Operations)', '[0.015842,0.006254,-0.067941,-0.010477,-0.059985,0.057417,-0.062611,0.013598,-0.077008,0.085192,-0.028160,0.023607,0.053523,-0.077503,-0.031824,-0.014743,-0.007280,-0.051586,0.032871,-0.050752,-0.105759,-0.052916,0.001878,-0.039548,0.000925,0.046253,-0.036347,0.030426,-0.047574,-0.111437,-0.049555,0.012657,0.024791,0.041118,0.031769,0.044125,0.025908,-0.000041,-0.079546,0.039521,-0.022169,-0.066207,-0.006340,0.034671,-0.032036,-0.046339,-0.058053,-0.071667,-0.088931,-0.010920,0.008296,-0.040582,0.042692,-0.026620,-0.036961,0.046473,0.032302,0.104012,-0.030464,-0.067410,0.007206,0.006295,-0.016453,0.050778,-0.021942,0.054952,0.001155,-0.016142,0.033816,-0.048253,-0.090572,0.054769,-0.139213,-0.028684,-0.054666,0.084121,-0.038464,-0.016255,0.115914,-0.045315,0.043338,0.014288,-0.089881,0.069083,-0.044843,-0.048801,0.022768,-0.059246,0.043445,-0.014697,0.054490,0.029219,0.048066,-0.039929,-0.114227,-0.046016,-0.040450,0.023634,-0.026109,0.060400,-0.024098,0.016050,-0.042492,-0.016435,-0.027731,0.001502,-0.038155,-0.036769,-0.011159,0.010800,0