INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (981, 'wanted', 368456, 'https://www.wanted.co.kr/wd/368456', 79, 'Associate Solutions Architect, APJ Startup CSC SA', 'The AWS Startup Solutions Architecture team is dedicated to working with these early stage startup companies as they build their businesses. We''re here to make sure that they can deploy the best, most scalable, and most secure architectures possible – and that they spend as little time and money as possible doing so. Amazon Web Services (AWS) is the world''s most comprehensive and broadly adopted cloud platform. We pioneered cloud computing and never stopped innovating — that''s why customers from the most successful startups to Global 500 companies trust our robust suite of products and services to power their businesses.', '• Work directly with a variety of early stage startup customers and help them make the best technical decisions
• Build enduring relationships with startup companies and establish yourself as a trusted advisor
• Keep skills fresh across AWS''s more than 175 services across a range of different categories
• Advocate with AWS product teams to ensure the right products are being built for startups
• Share knowledge broadly by working on technical content and presenting at events', '• Experience with one of the following programming languages: Python, Ruby, Node.js, C#, or C++
• Experience with two or more of the following: networking fundamentals, security, storage or databases (relational or NoSQL), operating systems (Unix, Linux, or Windows)', '• Experience implementing a cloud-based technology solution
• Experience in any of the following: Cloud Architecture, Systems Design, Software Development, Infrastructure Architecture, Data Engineering or DevOps', '• Diverse experiences and inclusive team culture
• Mentorship and career growth resources
• Work/life balance and flexible working culture
• Employee-led affinity groups and inclusion conferences (CORE, AmazeCon)
• Ongoing knowledge-sharing and career-advancing resources', '개발', '{"DevOps / 시스템 관리자","서버 개발자","소프트웨어 엔지니어"}', NULL, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-06-15 00:00:00+09', 'ACTIVE', '', '{Linux,Python,Node.js,NoSQL,C++,C#,UNIX,DevOps}', '{1459,1554,1547,2121,1786,1533,1808,1952}', true, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '경력무관', NULL, NULL, NULL, '2026-06-15 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Associate Solutions Architect, APJ Startup CSC SA', '[-0.048932,-0.061136,-0.007155,0.015499,-0.101567,-0.003070,-0.054399,0.066236,-0.036328,0.063145,-0.056666,-0.041943,0.040281,-0.008305,0.020995,0.000431,-0.015857,-0.037886,0.065170,-0.032823,-0.089082,-0.074921,-0.010146,-0.063936,-0.020372,-0.004447,0.096155,0.054342,-0.012755,-0.034183,-0.018992,-0.002742,0.035409,-0.014271,-0.019755,0.133668,-0.057413,-0.007715,-0.110642,-0.015832,0.010156,-0.032344,0.048100,-0.014548,-0.013592,-0.026375,-0.050786,0.011846,-0.132960,-0.085682,-0.015533,-0.042070,0.060546,-0.116309,-0.038845,0.041052,0.034051,0.042364,-0.020821,-0.044737,0.065217,-0.035256,-0.019838,-0.002456,0.044848,0.074071,0.030143,0.005475,-0.003813,-0.057333,-0.051877,-0.042317,-0.038925,0.015100,0.008720,0.032235,0.089797,-0.011459,0.065070,-0.005833,0.000295,0.052267,-0.001566,0.097377,-0.042628,0.032316,0.032536,0.038737,0.007983,0.018817,-0.056611,-0.002912,-0.009729,-0.044933,-0.002911,0.026801,0.035846,0.028970,-0.032365,0.113601,-0.083737,0.025965,-0.012661,-0.073048,-0.008387,0.028466,0.050036,-0.0604