INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (892, 'wanted', 360091, 'https://www.wanted.co.kr/wd/360091', 79, 'Data Center Operation Manager, ICN', 'AWS Infrastructure Services owns the design, planning, delivery, and operation of all AWS global infrastructure. In other words, we''re the people who keep the cloud running. We support all AWS data centers and all of the servers, storage, networking, power, and cooling equipment that ensure our customers have continual access to the innovation they rely on.', '• Hire, develop, build, and manage a team of Data Center Technicians, including the management of individual and team performance.
• Lead and supervise the team to be responsible for maintaining and troubleshooting system, hardware, and network device issues.
• Ensure effective and efficient management of data center operations, including ticket queue management, 7/24 shift arrangements, and hardware logistics.
• Inspire and guide improvement in team processes, technology innovation, and automation.
• Ensure all operational KPIs and metrics are being measured and met.
• Manage outage by severity level and act as the call leader.
• Be passionate about the quality and quantity of services being provided, and continuously strive to improve our Customer Experience.', '• 5+ years of people management experience
• 5+ years of Information Technology (IT) experience
• Experience communicating and delivering presentations to customers, stakeholders, and/or teammates
• Experience with budgeting, forecasting and variance analysis', '• Experience working in a data center or mission critical facility (example: hospital, military facility, public safety facility, etc.)
• Experience in infrastructure architecture, database architecture and networking
• Experience in project management including resource planning, managing schedules, reporting project status and prioritizing tasks
• Experience with lab safety, security and quality practices
• Speak, write, and read fluently in English', '• Diverse experiences valued — candidates from non-traditional paths encouraged to apply
• Inclusive team culture with employee-led and company-sponsored affinity groups
• Mentorship and career growth resources
• Work/life balance and flexibility as part of working culture
• Workplace accommodation and adjustment support during application and hiring process', '개발', '{"시스템,네트워크 관리자","DevOps / 시스템 관리자","개발 매니저"}', 5, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-05-07 00:00:00+09', 'ACTIVE', '', '{}', '{}', false, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '5~100년', NULL, NULL, NULL, '2026-05-07 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Data Center Operation Manager, ICN', '[0.013636,-0.014784,-0.042287,-0.005946,-0.070029,-0.039427,0.041828,-0.004063,-0.019977,0.081646,-0.033154,-0.012552,0.059586,-0.068594,-0.074631,-0.005991,-0.003477,-0.062628,0.031539,-0.013930,-0.040099,-0.028137,-0.064806,-0.012300,-0.044557,0.012895,-0.016330,0.001657,0.020542,-0.067247,0.014886,-0.042611,0.089896,0.082502,0.021845,0.015976,0.028094,0.014179,-0.040309,-0.021873,0.032444,0.001392,0.022490,-0.033419,0.019775,0.027492,-0.037584,-0.074834,-0.099747,-0.036894,-0.068132,-0.021255,0.079272,-0.011967,-0.074508,0.087795,0.048278,0.079132,0.015663,-0.111140,0.069160,-0.029228,-0.029443,0.029286,-0.051546,0.044271,-0.003199,-0.041893,-0.017816,-0.101818,-0.018522,0.033083,-0.086451,0.005833,-0.036494,0.085187,-0.048053,-0.004198,0.067378,-0.029584,-0.009572,0.025900,-0.020946,0.086735,-0.014594,-0.021117,0.061225,-0.025748,0.051363,-0.032693,0.055489,0.048412,0.042130,-0.054139,-0.024153,-0.069596,-0.020136,0.016274,-0.067798,0.087925,-0.028570,0.034849,-0.038336,-0.058824,-0.005575,-0.022507,0.017022,-0.082022,0.028952,0.049134,0.043143,0.007561,-0.126542,-0.032031,0.050226,0