INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (809, 'wanted', 365371, 'https://www.wanted.co.kr/wd/365371', 83, '플랫폼 개발/운영', '미래로 가는 모든 길에 코오롱베니트가 있습니다

코오롱베니트는 코오롱그룹의 IT서비스 전문기업입니다.
제조, 금융, 패션, 건설 등 각 산업 분야에서 쌓은 폭넓은 IT기술과 경험을 바탕으로 Big Data, IoT, Cloud, Smart Factory, Smart Construction 등 융·복합서비스 분야를 선도해 나가고 있습니다.
또한, IT솔루션 분야의 전문성과 파트너 네트워크를 통해 다양한 글로벌 IT솔루션의 No.1 Distributor로서의 입지를 공고히 하고 있습니다.
IT서비스 사업 분야에서도 그룹 내/외 IT아웃소싱을 비롯하여 전자공시 및 시장감시, 금융IT 사업 등을 활발히 펼쳐나가고 있습니다.
코오롱베니트(KOLON BENIT)의 BENIT는 Be in IT라는 의미로 ‘IT 세상에서 우리의 미래를 만들어갑니다’라는 뜻을 담고 있습니다.', '• 사내 업무 시스템 설계 및 개발', '• JAVA, VueJS, SpringBoot 기반의 사내 업무 시스템 개발
• 채용형태: 정규직 / 경력 3 년 이상
• 근무지: 과천

[필요 자격 및 스킬]
• 웹어플리케이션 개발
• SpringBoot 를 활용한 REST-API 설계 및 개발 가능자
• JPA 개발
• JAVA, JSP, Springboot, Vue.js 개발 가능자
• Vue3 개발 가능자
• Typescript, javascript 개발 가능자
• Figma 를 활용한 개발 경험
• 공통 컴포넌트 서비스 개발 경험', '• React 개발 경험
• 모바일 웹, 반응형 웹, 다양한 디바이스 환경 대응 경험
• AI 기반 코드작성, 테스트, 리팩토링 등 개발 workflow 에 AI 를 활용한 경험', '• 기업 내규', '개발', '{"자바 개발자","웹 퍼블리셔"}', 3, 8, false, true, 'regular', '한국', '경기', '과천시', '경기 과천시 코오롱로 11, 코오롱타워', 37.4254455, 126.9907579, false, NULL, '2026-06-01 00:00:00+09', 'ACTIVE', '', '{Java,React,JavaScript,TypeScript,JPA,Vue.js,Figma,VueJS,JSP,리팩토링,"Spring Boot"}', '{1540,1469,1541,1564,3451,10342,10172,1478,2735,3402,10169}', true, '100만원', 'https://static.wanted.co.kr/images/company/57362/rinegfcxwppd9u6x__1080_790.jpg', '{https://static.wanted.co.kr/images/company/57362/rinegfcxwppd9u6x__1080_790.jpg}', NULL, '2026-07-29 14:38:58.734046+09', '3~8년', NULL, NULL, NULL, '2026-06-01 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, '플랫폼 개발/운영', '[-0.136939,-0.059372,0.013546,-0.020004,-0.056274,0.042197,-0.113631,-0.030426,-0.037910,-0.023110,-0.081466,0.007289,-0.002004,0.036662,0.133917,-0.058298,-0.003502,0.012550,0.089686,-0.002342,-0.005004,-0.077991,0.046889,-0.052577,0.000362,0.025850,0.075253,-0.007195,-0.000599,-0.018262,0.027193,-0.003308,-0.015317,-0.065145,-0.006212,0.124696,-0.007676,0.004473,-0.080707,0.043804,-0.106908,0.035770,0.008760,-0.013183,-0.022255,0.037911,-0.045631,-0.012406,-0.090933,0.024908,-0.065950,-0.085518,0.018989,-0.047121,0.064957,-0.019450,0.046430,0.016610,-0.042448,-0.056603,0.009285,-0.092502,0.000057,-0.005641,-0.056546,0.010864,-0.004900,-0.015932,0.067054,-0.093339,-0.104567,0.030186,-0.033832,-0.033092,-0.068755,0.009084,-0.057383,0.002920,0.123163,-0.026543,0.004320,0.007535,0.071191,0.040729,0.027387,0.044579,-0.027436,0.020353,0.021473,0.090589,-0.029782,-0.041511,0.042158,-0.012300,-0.023378,0.026177,-0.041419,0.041995,0.041217,0.071154,-0.110591,-0.046430,0.054023,-0.026508,0.020471,-0.013764,-0.043368,0.049258,0.009951,-0.025040,-0.020668,-0.029575,-0.032611,0.031400,-0.018515,0.027616,-0.043533,-0.037660,-0.037572,0.108233,0.057404,-0.035838,0.098338,-0.020981,-0.067070,-0.009378,-0.068670,0.016