INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (791, 'wanted', 360092, 'https://www.wanted.co.kr/wd/360092', 79, 'Data Center Operation Manager', 'AWS Infrastructure Services owns the design, planning, delivery, and operation of all AWS global infrastructure. In other words, we''re the people who keep the cloud running. We support all AWS data centers and all of the servers, storage, networking, power, and cooling equipment that ensure our customers have continual access to the innovation they rely on.', '• Hire, develop, build, and manage a team of Data Center Technicians, including the management of individual and team performance.
• Lead and supervise the team to be responsible for maintaining and troubleshooting system, hardware, and network device issues.
• Ensure effective and efficient management of data center operations, including ticket queue management, 7/24 shift arrangements, and hardware logistics.
• Inspire and guide improvement in team processes, technology innovation, and automation.
• Ensure all operational KPIs and metrics are being measured and met.
• Manage outage by severity level and act as the call leader.
• Be passionate about the quality and quantity of services being provided, and continuously strive to improve our Customer Experience.', '• 5+ years of people management experience.
• 5+ years of experiences in managing an IT environment.
• In-depth knowledge and experience of change, problem and incident management.
• Demonstrated communication skill in presentation, open discussion, team coaching.
• Understanding in Financial budgeting, Capex and Opex concepts.', '• Cumulative experiences in Data Center Operations or similar roles in a mission critical environment.
• Cumulative experiences with information technology infrastructure domains such as compute server platforms, storage server platforms, server components, network devices, cabling and IT service delivery principles and best practices.
• Project Management skill.
• Experience in Safety and Security measures.
• Fluent in Korean and English.', '• Diverse experiences valued — non-traditional career paths welcome.
• Inclusive team culture with employee-led and company-sponsored affinity groups.
• Mentorship & career growth resources for continuous professional development.
• Work/life balance with flexibility as part of working culture.
• Workplace accommodations and adjustments available during application and hiring process.', '개발', '{"시스템,네트워크 관리자","DevOps / 시스템 관리자","개발 매니저"}', 5, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-05-07 00:00:00+09', 'ACTIVE', '', '{}', '{}', false, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '5~100년', NULL, NULL, NULL, '2026-05-07 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Data Center Operation Manager', '[0.025008,-0.024978,-0.048293,-0.013764,-0.069296,-0.035174,0.043585,-0.009794,-0.020634,0.094392,-0.036945,-0.017154,0.050373,-0.066075,-0.069578,-0.005904,0.003064,-0.074701,0.014347,-0.027603,-0.028875,-0.020605,-0.085428,-0.009582,-0.044025,0.001717,-0.012160,-0.011904,0.015995,-0.078633,0.012917,-0.031566,0.087786,0.078876,0.038071,0.005092,0.049704,0.010524,-0.031597,-0.027847,0.041527,-0.009162,0.028253,-0.038725,0.012861,0.014031,-0.027477,-0.055576,-0.095578,-0.047696,-0.058474,-0.006180,0.066407,-0.001508,-0.077776,0.067933,0.042717,0.093824,0.016904,-0.104695,0.077729,-0.011629,-0.013522,0.031798,-0.052297,0.042007,-0.025727,-0.053594,-0.027873,-0.085701,-0.034961,0.007408,-0.071470,-0.014228,0.003883,0.059292,-0.056082,-0.007950,0.055718,-0.019451,-0.025265,0.009296,-0.038585,0.078227,-0.042264,-0.036731,0.060183,-0.030550,0.059271,-0.012751,0.053266,0.051327,0.065946,-0.076677,-0.034369,-0.078204,-0.018164,0.026379,-0.041889,0.094261,-0.049726,0.062859,-0.027568,-0.073587,-0.013389,-0.040161,-0.000960,-0.072519,0.028508,0.059739,0.053611,-0.012680,-0.110393,0.008016,0.058785