INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (789, 'wanted', 362260, 'https://www.wanted.co.kr/wd/362260', 79, 'Data Center Operation Engineer, DCO (Data Center Operations)', 'AWS Infrastructure Services owns the design, planning, delivery, and operation of all AWS global infrastructure. In other words, we''re the people who keep the cloud running. We support all AWS data centers and all of the servers, storage, networking, power, and cooling equipment that ensure our customers have continual access to the innovation they rely on. Amazon Data Center Operations team deploys and maintains the servers and infrastructure in our data centers.', '• Maintain efficiently a high level of system reliability by prioritizing and resolving trouble tickets related to Systems and Network hardware problems
• Linux server and XEN service virtualization troubleshooting
• Remediate physical layer outages on both Systems & Network
• Participate in Data Center power & cooling events - 24x7 On-Call requirements and shift rotations
• Install & configure racks in-line with internal SLAs
• Triage & resolve trouble tickets for all devices
• Physical replacement of server and network devices
• Define metrics to increase our customer uptime
• Enforce Amazons Security Best Practices
• Interact with third-party vendors & contractors
• Contribute ideas to improve operational efficiency
• Participate in and deliver on a number of local/regional/global projects
• Participate in team meetings for metric analysis and project status updates
• Contribute in building the world''s largest Cloud infrastructure', '• Experience with computer hardware troubleshooting and repair
• 2+ years of server hardware troubleshooting and repair experience
• Speak, write, and read fluently in Korean', '• Experience working in a colocation data center facility
• Knowledge of fiber optic and copper cabling standards, testing equipment and troubleshooting methodologies
• Bilingual (Korean/English)', '• Diverse experiences and inclusive team culture
• Mentorship & Career Growth resources
• Work/Life Balance and flexibility as part of working culture
• Employee-led and company-sponsored affinity groups
• Workplace accommodation or adjustment support during application and hiring process', '개발', '{"시스템,네트워크 관리자","DevOps / 시스템 관리자","소프트웨어 엔지니어"}', 2, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-05-18 00:00:00+09', 'ACTIVE', '', '{}', '{}', false, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '2~100년', NULL, NULL, NULL, '2026-05-18 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Data Center Operation Engineer, DCO (Data Center Operations)', '[-0.014774,-0.019880,-0.012802,-0.055001,-0.079612,-0.003468,-0.045440,0.024941,-0.043287,0.100613,-0.034499,0.005189,0.103332,-0.067097,-0.091966,-0.006732,-0.010894,-0.020000,0.038006,-0.011657,-0.071194,-0.023914,-0.042120,-0.000536,-0.061219,0.042977,0.002191,0.028262,-0.014709,-0.108152,-0.002083,0.041977,0.018253,0.035930,0.035688,-0.010641,-0.005362,-0.088211,-0.052978,-0.012859,0.004334,-0.028186,0.002946,-0.058591,-0.009859,0.005717,0.001208,-0.046951,-0.079769,-0.028335,0.009547,0.062956,0.058173,-0.022913,-0.091687,0.048235,0.066719,0.090316,0.001749,-0.089487,0.135289,0.005530,-0.002464,0.030452,-0.015159,0.060268,0.041968,-0.015285,-0.016120,-0.076914,-0.061976,0.030177,-0.085197,-0.037467,-0.021659,0.091660,-0.022777,-0.072040,0.063549,-0.025149,0.001869,-0.023321,-0.064794,0.058617,-0.077598,-0.030878,0.074273,-0.028834,0.037109,-0.072459,0.065664,0.067944,0.012391,-0.024889,-0.029094,-0.067110,-0.018335,0.028030,-0.036432,0.101156,-0.040769,0.087735,-0.046253,-0.054400,0.008893,-0.010284,0.023946,-0.089458,-0.012873,0.012925,0.015470,-0.008383