INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (776, 'wanted', 370836, 'https://www.wanted.co.kr/wd/370836', 79, 'Solutions Architect - Startup, Korea', 'Do you like startups? Are you interested in cloud computing? Yes? We have a role you might find interesting. The AWS Startup Solutions Architecture team is dedicated to working with these early stage startup companies as they build their businesses. We''re here to make sure that they can deploy the best, most scalable, and most secure architectures possible – and that they spend as little time and money as possible doing so.', '• Work directly with early stage startup customers to help them make the best technical decisions
• Deploy scalable and secure architectures for startup customers
• Build enduring relationships with startup companies and establish yourself as a trusted advisor
• Keep skills fresh across AWS''s more than 175 services
• Advocate with AWS product teams to ensure the right products are built for startups
• Share knowledge broadly by working on technical content and presenting at events', '• 5+ years of specific technology domain areas (e.g. software development, cloud computing, systems engineering, infrastructure, security, networking, data & analytics) experience
• 2+ years of design, implementation, or consulting in applications and infrastructures experience
• 2+ years of IT development or implementation/consulting in the software or Internet industries experience', '• Experience working within software development or Internet-related industries
• Experience migrating or transforming legacy customer solutions to the cloud
• Experience working with AWS technologies from a dev/ops perspective', '• Diverse experiences valued — non-traditional career paths welcome
• Inclusive team culture with employee-led affinity groups
• Mentorship & career growth resources
• Work/life balance and flexibility as part of working culture
• Ongoing learning experiences including CORE and AmazeCon conferences', '개발', '{"DevOps / 시스템 관리자","서버 개발자","소프트웨어 엔지니어"}', 5, 100, false, true, 'regular', '한국', '서울', '강남구', '서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)', 37.5030426, 127.041588, false, NULL, '2026-06-25 00:00:00+09', 'ACTIVE', '', '{AWS,Consulting}', '{1698,1573}', true, '50만원', 'https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png', '{https://static.wanted.co.kr/images/company/56940/edysu2unsddfbodt__1080_790.png,https://static.wanted.co.kr/images/company/56940/ahvpyffpurjfg3te__1080_790.png,https://static.wanted.co.kr/images/company/56940/vzi7gfzbtw3gwgac__1080_790.png}', NULL, '2026-07-29 14:38:58.734046+09', '5~100년', NULL, NULL, NULL, '2026-06-25 00:00:00+09', NULL, NULL, NULL, '2026-07-30 22:52:23.175012+09', '2026-07-30 22:52:23.175012+09', false, NULL, 'Solutions Architect - Startup, Korea', '[-0.034130,-0.045198,0.005307,0.049514,-0.055629,0.010852,-0.039357,0.030215,-0.036568,0.094908,-0.086599,0.010629,0.031066,0.007623,0.050913,0.045437,-0.067714,-0.087131,0.038953,0.004989,-0.050577,-0.068640,-0.023832,-0.046738,-0.016514,0.029232,0.103411,0.030145,0.005893,-0.057316,-0.003206,0.031196,0.013112,0.046795,0.022855,0.100232,-0.034733,0.008266,-0.103298,-0.033719,0.042637,0.028689,0.031612,-0.038415,0.041838,0.049263,0.028217,0.058307,-0.142986,-0.068515,-0.012131,-0.047572,0.059532,-0.049805,-0.046620,0.046906,0.050250,0.008100,-0.026488,-0.083765,0.090961,-0.042184,-0.015542,-0.019835,0.027934,0.067287,-0.017470,0.003911,-0.000134,-0.003994,-0.007456,-0.071232,0.000361,0.011084,0.057525,0.010884,0.085866,0.004700,0.050744,-0.005243,-0.009839,-0.021495,-0.015223,0.078037,-0.051593,0.014309,0.009135,0.017112,0.058796,0.040537,-0.016790,-0.004493,0.017166,-0.045985,0.025738,-0.013713,0.020111,-0.001570,-0.030734,0.110184,-0.007294,0.035750,0.000506,-0.126814,0.003142,0.005563,0.008805,-0.060225,-0.022226,0.028701,0.006568,-0.048922,-0.004690,-0.038382,0.065678,-0.020670