INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (704, 'wanted', 368811, 'https://www.wanted.co.kr/wd/368811', 447, 'IT부문 증권 업무시스템 개발', '• 증권 업무시스템 개발', '• 금융상품(채권, ELS/DLS, CMA, CD/CP/RP/전단채) 업무 시스템 개발 및 유지보수
• 집합투자증권, 랩, ISA, 연금, 신탁 업무 시스템 개발 및 유지보수', '• 4년제 대학교 이상 학위 취득자
• 전산 전공 또는 실무 경험 보유자
