INSERT INTO public.job_postings (id, source, external_id, source_url, company_id, "position", intro, main_tasks, requirements, preferred_points, benefits, category_parent, category_child, career_min, career_max, is_newbie, is_expert, employment_type, location_country, location_city, location_district, location_full, geo_lat, geo_lng, is_remote, due_time, confirm_time, status, hire_rounds, skill_tags, skill_tag_ids, skills_inferred, reward_total, thumbnail_url, image_urls, raw, collected_at, career_level, categories, deadline_at, editor_note, posted_at, skills, job_category_id, region_id, created_at, updated_at, remote_available, salary_disclosed, title, embedding) VALUES (678, 'wanted', 370326, 'https://www.wanted.co.kr/wd/370326', 6, '솔루션 및 미들웨어 운영자', '㈜디비아이엔씨는 1977년에 설립된 회사로 자본금 910억 6,316만원, 매출액 5,874억, 사원수 1,000명 규모의 대기업입니다.', '• 솔루션 및 미들웨어 운영
