• 경조 휴가 및 경조비 지원', NULL, '{"자바 개발자","서버 개발자"}', 4, 10, false, NULL, 'regular', NULL, '서울', '중구', '서울 중구 동호로20길 6, 401호', NULL, NULL, NULL, NULL, NULL, 'ACTIVE', NULL, '{Git,Linux,MySQL,Java,JavaScript,SQL,TypeScript,AWS,PostgreSQL,NodeJS,"Spring Framework",JPA,"Spring Boot"}', '{}', false, '100만원', 'https://static.wanted.co.kr/images/company/30522/xnke38dfzxvl4f00__1080_790.jpg', '{}', NULL, '2026-08-04 23:24:48.716165+09', '4~10년', '자바 개발자,서버 개발자', '2026-08-31 00:00:00+09', NULL, '2026-08-03 00:00:00+09', NULL, NULL, NULL, '2026-08-04 23:24:49.082774+09', '2026-08-05 01:22:13.384491+09', false, NULL, '백엔드 개발자 (4년 이상~)', NULL);
